"""Migrated Meridian CRM 4.2 account validation rules."""

from typing import Any


def _value(record: dict | None, key: str) -> Any:
    """Return a field value, treating missing and None values as empty strings."""
    if record is None:
        return ""
    value = record.get(key, "")
    return "" if value is None else value


def _number(value: Any) -> float:
    """Apply legacy numeric coercion: empty and missing values become zero."""
    if value is None or value == "":
        return 0.0
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return 0.0


def _nvl(value: Any, default: Any) -> Any:
    """Return default only for legacy empty/missing/null values."""
    return default if value is None or value == "" else value


def _length(value: Any) -> int:
    """Return legacy string length, with missing/null values treated as empty."""
    return len("" if value is None else str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image against migrated VRL rules."""
    del today  # Included for the fixed interface; unused by these rules.

    errors: list[dict] = []
    old_record = old if event == "UPDATE" and old is not None else {}

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    # ACC-001
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            add("E1001", "Account name too short")

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            add("E1002", "Invalid account type")

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        if _number(_nvl(_value(record, "ANN_REV"), 0)) < 0:
            add("E1003", "Annual revenue negative")

    # ACC-004
    if event == "UPDATE":
        releasing_hold_without_limit = (
            _value(old_record, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releasing_hold_without_limit:
            add("E1004", "Cannot release credit hold with zero credit limit")

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            add("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
